input.new_string:
    The array only exists if all the types can be used as a metatype:
    either declared with Q_DECLARE_METATYPE (or built-in), or complete
    types that the meta-type system handles automatically (Q_GADGET,
    Q_ENUM, pointers to QObject subclasses, ...). The latter is detected
    the same way moc-generated code does, via
    qTryMetaTypeInterfaceForType(). Unique is passed to its completeness
    test, because completeness of a type may differ between translation
    units for the same argument list.
    If one of the types is not usable, the function returns nullptr and the
    argument types are resolved from the signal's QMetaMethod instead.
*/
template <typename Unique, typename Arg>
constexpr bool isConnectionTypeUsable()
{
    if constexpr (bool(QMetaTypeId2<Arg>::Defined))
        return true;
    else
        return qTryMetaTypeInterfaceForType<Unique, Arg>() != nullptr;
}

template <typename Unique, typename Arg>
int connectionTypeId()
{
    if constexpr (bool(QMetaTypeId2<Arg>::Defined))
        return QMetaTypeIdHelper<Arg>::qt_metatype_id();
    else
        return QMetaType(qTryMetaTypeInterfaceForType<Unique, Arg>()).id();
}

template <typename ArgList, typename Unique> struct ConnectionTypes;
template <typename Unique> struct ConnectionTypes<List<>, Unique>
{ static const int *types() { return nullptr; } };
template <typename... Args, typename Unique> struct ConnectionTypes<List<Args...>, Unique>
{
    static const int *types()
    {
        if constexpr ((isConnectionTypeUsable<Unique, Args>() && ...)) {
            static const int t[sizeof...(Args) + 1] = { connectionTypeId<Unique, Args>()..., 0 };
            return t;
        } else {
            return nullptr;
        }
    }
};

